/* Reference atmosphere and trajectories are confined to the Hero. */
(()=>{const hero=document.querySelector('#accueil'),scene=hero.querySelector('.orbit-universe');for(const cls of ['path-four','path-five','path-cold']){const line=document.createElement('div');line.className=`orbit-path ${cls}`;line.setAttribute('aria-hidden','true');scene.append(line)}const stars=document.createElement('div');stars.className='reference-starfield';stars.setAttribute('aria-hidden','true');for(let i=0;i<22;i++){const dot=document.createElement('i');dot.style.left=`${(i*31.37+2)%99}%`;dot.style.top=`${(i*17.13+8)%97}%`;dot.style.setProperty('--star-delay',`${-i*.63}s`);stars.append(dot)}hero.append(stars);const grain=document.createElement('div');grain.className='reference-grain';grain.setAttribute('aria-hidden','true');hero.append(grain)})();
